package com.gomgomapps.math.core;
import java.util.*;import java.util.regex.*;
/** Three public terms are rounded separately; the estimate is not their exact sum. */
public final class ThreeNumberEstimation {
 private ThreeNumberEstimation(){}
 public static final String ID="threeNumberEstimate";
 public static final Catalog.Skill SKILL=new Catalog.Skill(ID,"세 수의 합 어림하기",6,1,1,"","threeEstimate",1000000,"el_round","세 수를 각각 반올림한 뒤 더해 합을 어림한다.");
 public record Givens(int first,int second,int third,int unit){public int[] terms(){return new int[]{first,second,third};}}
 private static final Pattern PROMPT=Pattern.compile("(0|[1-9][0-9]{0,6}) \\+ (0|[1-9][0-9]{0,6}) \\+ (0|[1-9][0-9]{0,6})\n각 수를 (10|100|1000|10000|100000)의 자리까지 반올림한 뒤 더하세요[.]");
 static long combinations(int maximum){return maximum<0?0:(maximum+1L)*(maximum+2L)*(maximum+3L)/6;}
 static int[] at(int maximum,long index){long count=combinations(maximum);if(index<0||index>=count)throw new IndexOutOfBoundsException();int low=0,high=maximum+1;while(low+1<high){int mid=(low+high)/2;if(count-combinations(maximum-mid)<=index)low=mid;else high=mid;}int first=low,remaining=maximum-first;long residual=index-(count-combinations(remaining));low=0;high=remaining+1;while(low+1<high){int mid=(low+high)/2;long prefix=mid*(2L*remaining+3-mid)/2;if(prefix<=residual)low=mid;else high=mid;}int second=low,third=(int)(residual-second*(2L*remaining+3-second)/2);return new int[]{first,second,third};}
 static Question next(Random random,CurriculumLimits limits,Map<String,Integer> recent){int maximum=Math.min(1000000,limits.wholeMaximum(1000000)),minimum=limits.givenMinimum(0);int[] units=limits.roundingUnits();if(minimum<0||maximum<0||(long)minimum*3>maximum||Arrays.stream(units).anyMatch(u->!Set.of(10,100,1000,10000,100000).contains(u)))throw new IllegalArgumentException("Three-number estimation curriculum");int slack=maximum-3*minimum;long count=combinations(slack)*units.length;java.util.function.LongFunction<Question> factory=i->{int[] t=at(slack,i/units.length);return make(t[0]+minimum,t[1]+minimum,t[2]+minimum,units[(int)(i%units.length)]);};return count<=Integer.MAX_VALUE?IndexedQuestionSupply.choose((int)count,i->factory.apply(i),random,limits,recent):IndexedQuestionSupply.chooseLarge(count,factory,random,limits,recent);}
 public static Question make(int first,int second,int third,int unit){if(first<0||second<0||third<0||(long)first+second+third>1000000||!Set.of(10,100,1000,10000,100000).contains(unit))throw new IllegalArgumentException("Three-number estimation bounds");Question q=new Question(ID,first+" + "+second+" + "+third+"\n각 수를 "+unit+"의 자리까지 반올림한 뒤 더하세요.","",""+estimate(new Givens(first,second,third,unit)));q.stepSupport=false;attach(q);return q;}
 public static Givens read(Question q){if(q==null||!ID.equals(q.skillId)||q.prompt==null)return null;Matcher m=PROMPT.matcher(q.prompt);if(!m.matches())return null;int a=Integer.parseInt(m.group(1)),b=Integer.parseInt(m.group(2)),c=Integer.parseInt(m.group(3));return (long)a+b+c<=1000000?new Givens(a,b,c,Integer.parseInt(m.group(4))):null;}
 public static int round(int value,int unit){return (value+unit/2)/unit*unit;}
 public static int estimate(Givens g){return Arrays.stream(g.terms()).map(n->round(n,g.unit)).sum();}
 public static void attach(Question q){Givens g=read(q);if(g==null)return;StudyGuide guide=new StudyGuide().transfer(false);guide.teachingVersion="three-number-estimation-v1";guide.step("반올림할 자리의 값을 쓰세요.","반올림할 자리 = ","",""+g.unit);int term=0;for(int n:g.terms()){String label=List.of("첫 수","둘째 수","셋째 수").get(term++);int digit=n/(g.unit/10)%10;guide.step("바로 아래 자리의 숫자를 쓰세요.",label+"의 바로 아래 자리 숫자 = ","",""+digit);Map<String,String> choices=new LinkedHashMap<>();choices.put("raise","올리기");choices.put("keep","그대로");guide.choice("5 이상이면 올리기, 5 미만이면 그대로를 고르세요.",choices,digit>=5?"raise":"keep");guide.step("이 수를 지정한 자리까지 반올림하세요.",label+"의 반올림값 = ","",""+round(n,g.unit));}guide.step("반올림한 세 수를 더하세요.","반올림한 세 수의 합 = ","",""+estimate(g));q.studyGuide=guide;}
 public static Checker.Result check(Question q,List<String> answers){Givens g=read(q);if(g==null||answers==null||answers.size()!=1||answers.get(0)==null||!answers.get(0).trim().matches("0|[1-9][0-9]{0,6}"))return new Checker.Result(Checker.Status.INPUT_NEEDED,0,"수 입력 필요");boolean correct=Integer.parseInt(answers.get(0).trim())==estimate(g);return new Checker.Result(correct?Checker.Status.CORRECT:Checker.Status.WRONG_ANSWER,correct?-1:0,correct?"정답":"이 답 확인");}
}
